$(document).ready(function(){$("#cbsearchtype a").on({click:function(e){e.preventDefault();$("#SearchType").val();e=$(this).text().toLowerCase();0<$("#SearchType option[value='"+e+"']").length&&($("#SearchType option:selected").removeAttr("selected"),$("#SearchType option[value='"+e+"']").attr("selected","selected"),$(this).parents("ul").find(".active").removeClass("active"),$(this).parent().addClass("active"))}})});